import AppKit
import RFBKit

/// What the bridge reads from the local pasteboard.
enum PasteboardContent: Equatable {
    case text(String)
    /// Marked concealed, transient or auto-generated (nspasteboard.org): never shared.
    case excluded
    /// No plain text (empty, image, file…).
    case none
}

/// The local pasteboard as the bridge uses it. `SystemPasteboard` in the app; a fake in tests (the
/// tests never touch the real pasteboard).
@MainActor
protocol ClipboardPasteboard: AnyObject {
    /// `NSPasteboard.changeCount`: reading it does not read the contents.
    var changeCount: Int { get }
    func read() -> PasteboardContent
    func write(_ text: String)
}

/// `NSPasteboard.general`, plain text only.
@MainActor
final class SystemPasteboard: ClipboardPasteboard {
    /// nspasteboard.org markers: password managers mark secrets concealed; transient and
    /// auto-generated items are not meant to be kept or synced either.
    static let excludedTypes: Set<NSPasteboard.PasteboardType> = [
        NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType"),
        NSPasteboard.PasteboardType("org.nspasteboard.TransientType"),
        NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType"),
    ]

    private let pasteboard: NSPasteboard

    init(pasteboard: NSPasteboard = .general) {
        self.pasteboard = pasteboard
    }

    var changeCount: Int { pasteboard.changeCount }

    func read() -> PasteboardContent {
        // Denied in System Settings › Privacy & Security › Paste from Other Apps: nothing to read.
        if #available(macOS 15.4, *), pasteboard.accessBehavior == .alwaysDeny { return .none }
        return Self.content(types: pasteboard.types ?? []) { [pasteboard] in pasteboard.string(forType: .string) }
    }

    /// The decision, apart from `NSPasteboard` (unit-tested): the types are metadata, so checking them
    /// reads no contents; `string` is called only for a plain-text item without a marker.
    static func content(types: [NSPasteboard.PasteboardType], string: () -> String?) -> PasteboardContent {
        guard Set(types).isDisjoint(with: excludedTypes) else { return .excluded }
        guard types.contains(.string), let text = string() else { return .none }
        return .text(text)
    }

    func write(_ text: String) {
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
    }
}

/// A private pasteboard for the hosted tests and the Debug `-LibraryDemo` sessions: the real one is
/// never read or written there.
@MainActor
final class InMemoryPasteboard: ClipboardPasteboard {
    private(set) var changeCount = 0
    var content: PasteboardContent = .none {
        didSet { changeCount += 1 }
    }
    /// Contents reads (a changed count alone must not cause one).
    private(set) var reads = 0

    init() {}

    func read() -> PasteboardContent {
        reads += 1
        return content
    }

    func write(_ text: String) {
        content = .text(text)
    }
}

/// Shared Clipboard for one session (PRD › Shared Clipboard, AppFlow › Session Window): plain text
/// both ways while sharing is on (Machine.sharedClipboard, then the toolbar toggle).
///
/// - Local → remote: only while the session runs **and** its window is key. The pasteboard has no
///   change notification, so the bridge compares `changeCount` when the window becomes key and then
///   every `pollInterval` while it stays key; a background session never reads the pasteboard, so
///   text copied for another app or session does not leak to it. The contents are read only when the
///   count changed. Items marked concealed/transient/auto-generated are skipped, and so is text over
///   `ServerMessageDecoder.maxCutTextLength` UTF-8 bytes (`onTooLarge`: "Clipboard too large").
/// - Remote → local: only while the session runs **and** its window is key (T5.3 M1): a background
///   tab or a server that writes while the user works elsewhere never replaces the local pasteboard.
///   The latest remote text is kept and written when the window becomes key (or the session starts
///   with its window key), unless the local pasteboard changed since it arrived: a later local copy
///   wins. C0 control characters other than tab, line feed and carriage return, DEL and C1 controls are removed first.
/// - No echo: text that came from one side is never sent back to it. The change count produced by
///   writing the remote text is recorded, so the next poll does not even read it. A server text equal
///   to the last one exchanged (or to the form the server holds it in, `ClipboardShare.sent(echo:)`:
///   Latin-1 `?`, LF line ends) is skipped only while the local pasteboard is unchanged since that
///   exchange: after a local copy elsewhere, the same remote text is a new copy and is written.
/// - Clipboard contents are never logged.
@MainActor
final class ClipboardBridge {
    var isEnabled: Bool {
        didSet {
            guard isEnabled != oldValue else { return }
            lastShared = nil
            lastEcho = nil
            pendingRemote = nil
            lastSeenChangeCount = nil   // turned on again: offer the current pasteboard
            updatePolling()
            if isEnabled { poll() }
        }
    }
    private(set) var isRunning = false
    private(set) var isKey = false

    private let pasteboard: any ClipboardPasteboard
    private let pollInterval: Duration?
    /// Hands local text to the session (set by its owner).
    var send: (String) -> Void = { _ in }
    /// "Clipboard too large" (set by its owner).
    var onTooLarge: () -> Void = {}
    private var lastSeenChangeCount: Int?
    /// The last text exchanged either way.
    private var lastShared: String?
    /// `lastShared` as the server holds it, once the send reported it.
    private var lastEcho: String?
    /// The latest remote text not written yet (session not running or window not key), with the
    /// local change count when it arrived.
    private var pendingRemote: (text: String, changeCount: Int)?
    private var pollTask: Task<Void, Never>?

    /// `pollInterval` nil: no timer (tests call `poll()`).
    init(pasteboard: any ClipboardPasteboard, isEnabled: Bool, pollInterval: Duration? = .milliseconds(500)) {
        self.pasteboard = pasteboard
        self.isEnabled = isEnabled
        self.pollInterval = pollInterval
    }

    /// First frame: the current pasteboard is offered if the window is key.
    func sessionStarted() {
        isRunning = true
        lastSeenChangeCount = nil
        lastShared = nil
        lastEcho = nil
        writePendingRemote()
        updatePolling()
        poll()
    }

    func sessionStopped() {
        isRunning = false
        pendingRemote = nil
        updatePolling()
    }

    func windowKeyChanged(_ key: Bool) {
        guard key != isKey else { return }
        isKey = key
        updatePolling()
        guard key else { return }
        writePendingRemote()   // first: a write records its change count, so the poll does not send it back
        poll()
    }

    /// Sends the local text if the pasteboard changed since the last look.
    func poll() {
        guard isEnabled, isRunning, isKey else { return }
        let count = pasteboard.changeCount
        guard count != lastSeenChangeCount else { return }
        lastSeenChangeCount = count
        guard case .text(let text) = pasteboard.read(), text != lastShared else { return }
        guard text.utf8.count <= ServerMessageDecoder.maxCutTextLength else {
            onTooLarge()
            return
        }
        lastShared = text
        lastEcho = nil
        send(text)
    }

    /// What became of `send(text)` (RFBKit's answer).
    func shared(_ text: String, outcome: ClipboardShare) {
        guard text == lastShared else { return }   // a newer exchange since
        switch outcome {
        case .sent(let echo): lastEcho = echo
        case .tooLarge: onTooLarge()
        case .notSharing: break
        }
    }

    /// Text from the server: written now if the session runs and its window is key, else kept (the
    /// latest only) for the next time it is.
    func receive(_ text: String) {
        guard isEnabled else { return }
        let text = Self.sanitized(text)
        guard isRunning, isKey else {
            pendingRemote = (text, pasteboard.changeCount)
            return
        }
        write(text)
    }

    /// Removes the C0 controls except tab, line feed and carriage return, DEL and the C1 controls
    /// (T5.3 M1): a server's text pasted into a terminal must not carry escape sequences (ESC, or the
    /// 8-bit CSI U+009B), NULs or deletes.
    static func sanitized(_ text: String) -> String {
        guard text.unicodeScalars.contains(where: isStripped) else { return text }
        var kept = String.UnicodeScalarView()
        kept.append(contentsOf: text.unicodeScalars.filter { !isStripped($0) })
        return String(kept)
    }

    private static func isStripped(_ scalar: Unicode.Scalar) -> Bool {
        (scalar.value < 0x20 && scalar != "\t" && scalar != "\n" && scalar != "\r") || (0x7F...0x9F).contains(scalar.value)
    }

    private func writePendingRemote() {
        guard isRunning, isKey, let pending = pendingRemote else { return }
        pendingRemote = nil
        // Copied locally since the remote text came: the newer local copy stays.
        guard pasteboard.changeCount == pending.changeCount else { return }
        write(pending.text)
    }

    private func write(_ text: String) {
        let unchangedLocally = pasteboard.changeCount == lastSeenChangeCount
        if unchangedLocally, text == lastShared || text == lastEcho { return }
        lastShared = text
        lastEcho = nil
        pasteboard.write(text)
        lastSeenChangeCount = pasteboard.changeCount
    }

    private func updatePolling() {
        let wanted = isEnabled && isRunning && isKey && pollInterval != nil
        if !wanted {
            pollTask?.cancel()
            pollTask = nil
            return
        }
        guard pollTask == nil, let pollInterval else { return }
        pollTask = Task { [weak self] in
            while !Task.isCancelled {
                try? await Task.sleep(for: pollInterval)
                guard !Task.isCancelled, let self else { return }   // the bridge went away: stop
                self.poll()
            }
        }
    }
}
